// SplitName splits SECTION.KEY at the last dot, since section names may
// contain dots but keys never do. ok is false if name has no dot.
func SplitName(name string) (section, key string, ok bool) {
	i := strings.LastIndex(name, ".")
	if i < 0 {
		return "", name, false
	}
	return name[:i], name[i+1:], true
}
EOF
